namespace CSharpPracticum.Tasks.Level2;
internal interface IShape{double Area();double Perimeter();} internal class Circle(double r):IShape{public double Area()=>Math.PI*r*r;public double Perimeter()=>2*Math.PI*r;public override string ToString()=>"Круг";} internal class Rectangle(double w,double h):IShape{public double Area()=>w*h;public double Perimeter()=>2*(w+h);public override string ToString()=>"Прямоугольник";} internal class Triangle(double a,double b,double c):IShape{public double Perimeter()=>a+b+c;public double Area(){double p=Perimeter()/2;return Math.Sqrt(p*(p-a)*(p-b)*(p-c));}public override string ToString()=>"Треугольник";}
internal class Task25_Shapes:ITask{public string Title=>"Задание 25: Интерфейс IShape и сортировка фигур";public string Description=>"Посчитать характеристики фигур и упорядочить их по площади.";public string[] Requirements=>new[]{"IShape.Area и Perimeter.","Circle, Rectangle и Triangle.","Список из 5+ фигур отсортировать по площади и показать до и после."};public void Run(){List<IShape> s=new(){new Circle(2),new Rectangle(2,3),new Triangle(3,4,5),new Circle(1),new Rectangle(4,5)};Console.WriteLine("До:");foreach(var x in s)Console.WriteLine($"{x}: {x.Area():F2}");s.Sort((a,b)=>a.Area().CompareTo(b.Area()));Console.WriteLine("После:");foreach(var x in s)Console.WriteLine($"{x}: {x.Area():F2}");}}
